const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;padding:10px;display:flex;flex-direction:column;gap:6px;color:var(--ink);font:12px/1.35 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;overflow:hidden;min-width:0;min-height:0}\n.card *{box-sizing:border-box}\n.card[data-size=\"3x3\"]{padding:8px;gap:5px}\n.card button,.card input,.card select{font:inherit;color:var(--ink)}\n.card button{cursor:pointer}\n.btn{height:30px;padding:0 8px;border-radius:8px;border:1px solid var(--line);background:var(--panel-paper);white-space:nowrap;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis}\n.btn.primary{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n.btn.danger{border-color:#B4533A}\n.btn.sure{background:#B4533A;color:#FFFFFF;border-color:transparent;font-weight:600}\n.btn:disabled,.ib:disabled{opacity:.4;cursor:default}\n.btns,.ffoot{display:flex;gap:6px;flex:none}\n.ib{width:28px;height:28px;flex:none;border-radius:50%;border:1px solid var(--line);background:var(--panel-paper);padding:0;line-height:1;font-size:16px}\n.ib.add{background:var(--accent);color:var(--on-accent);border-color:transparent}\n\n.sum{display:flex;flex-direction:column;gap:5px;min-width:0;flex:none}\n.nav,.head{display:flex;align-items:center;gap:4px;flex:none;min-width:0}\n.nav .lbl,.ttl{flex:1;min-width:0;text-align:center;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.ttl{text-align:left}\n.lead{display:flex;flex-direction:column;min-width:0}\n.lab{color:var(--muted);font-size:11px}\n.big{font-size:26px;line-height:1.15;font-weight:700;white-space:nowrap;font-variant-numeric:tabular-nums;overflow:hidden;text-overflow:ellipsis}\n.card[data-size=\"6x3\"] .big,.card[data-size=\"3x6\"] .big{font-size:28px}\n.card[data-size=\"6x6\"] .big{font-size:34px}\n.bar{height:8px;border-radius:4px;background:var(--soft);overflow:hidden;flex:none}\n.bar i{display:block;height:100%;background:var(--accent);border-radius:4px}\n.bar.over i{background:#B4533A}\n.meta{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:0 6px;color:var(--muted);font-size:11px}\n.meta span{white-space:nowrap}\n.bud{border:0;background:none;padding:3px 0;color:var(--ink);font-size:11px;white-space:nowrap;text-decoration:underline dotted}\n\n.tabs{display:flex;gap:3px;background:var(--soft);padding:2px;border-radius:8px;flex:none}\n.tabs button{flex:1;min-width:0;border:0;background:transparent;height:24px;border-radius:6px;padding:0 2px;white-space:nowrap}\n.tabs button.on{background:var(--accent);color:var(--on-accent);font-weight:600}\n.scroll{flex:1;min-height:0;min-width:0;overflow:auto}\n.detail{display:flex;flex-direction:column;gap:5px;flex:1;min-height:0}\n.cols{display:flex;gap:10px;flex:1;min-height:0;min-width:0}\n.pane{display:flex;flex-direction:column;gap:6px;min-width:0;min-height:0}\n.pane.p1{flex:0 0 44%}\n.pane.p2{flex:1}\n.pane.spread{justify-content:space-between}\n.card[data-size=\"6x6\"] .pane.p2{border-left:1px solid var(--line);padding-left:10px}\n.st{color:var(--muted);font-size:11px;flex:none}\n.empty{color:var(--muted);padding:12px 4px;text-align:center}\n\n.crow{display:grid;grid-template-columns:28px minmax(20px,1fr) auto;align-items:center;gap:6px;padding:5px 0}\n.cn{white-space:nowrap}\n.cb{height:6px;border-radius:3px;background:var(--soft);overflow:hidden;min-width:0}\n.cb i{display:block;height:100%;background:var(--accent-alt);border-radius:3px}\n.ca{white-space:nowrap;text-align:right;font-variant-numeric:tabular-nums}\n.rrow{display:grid;grid-template-columns:34px minmax(0,1fr) auto;gap:6px;align-items:center;width:100%;text-align:left;padding:6px 2px;border:0;border-bottom:1px solid var(--line);background:transparent;border-radius:0}\n.rd{color:var(--muted);font-size:11px;white-space:nowrap}\n.rm{display:flex;flex-direction:column;min-width:0}\n.rm b{font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.rm em{font-style:normal;color:var(--muted);font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.ra{white-space:nowrap;font-weight:600;font-variant-numeric:tabular-nums}\n\n.form{display:flex;flex-direction:column;gap:6px;flex:1;min-height:0}\n.fbody{flex:1;min-height:0;overflow:auto;display:flex;flex-direction:column;gap:6px}\n.frow{display:grid;grid-template-columns:30px minmax(0,1fr);align-items:center;gap:6px}\n.frow.wide{grid-template-columns:minmax(0,1fr);gap:4px}\n.frow span{color:var(--muted);font-size:11px;white-space:nowrap}\n.card input,.card select{height:30px;width:100%;min-width:0;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);padding:0 6px}\n.card[data-size=\"3x3\"] input,.card[data-size=\"3x3\"] select{height:28px}\n.hint{color:var(--muted);font-size:11px}\n.err{font-size:11px;border-left:3px solid #B4533A;padding-left:6px;flex:none}\n.errgap{display:none}\n";
const CATS=['餐饮','交通','购物','住房','日用','娱乐','医疗','其他'];
const DEFAULT_BUDGET=3000;

function initialize(s){
  const b=(s&&typeof s==='object')?s:{};
  const ok=typeof b.budget==='number'&&b.budget>0&&Array.isArray(b.records)&&b.budgets&&typeof b.budgets==='object';
  if(ok)return s;
  return {...b,
    budget:(typeof b.budget==='number'&&b.budget>0)?b.budget:DEFAULT_BUDGET,
    budgets:(b.budgets&&typeof b.budgets==='object'&&!Array.isArray(b.budgets))?b.budgets:{},
    records:Array.isArray(b.records)?b.records:[]};
}
function norm(s){
  const b=(s&&typeof s==='object')?s:{};
  return {
    budget:(typeof b.budget==='number'&&b.budget>0)?b.budget:DEFAULT_BUDGET,
    budgets:(b.budgets&&typeof b.budgets==='object'&&!Array.isArray(b.budgets))?b.budgets:{},
    records:Array.isArray(b.records)?b.records.filter(r=>r&&typeof r.amount==='number'&&typeof r.date==='string'):[]
  };
}
function r2(n){return Math.round(n*100)/100}
function fmt(n){
  const r=r2(n);
  return r.toLocaleString('zh-CN',{minimumFractionDigits:Number.isInteger(r)?0:2,maximumFractionDigits:2});
}
function monthOf(d){return String(d||'').slice(0,7)}
function monthLabel(m){return m.slice(0,4)+'年'+(+m.slice(5,7))+'月'}
function nextMonth(m){
  const y=+m.slice(0,4),mo=+m.slice(5,7);
  return mo>=12?(y+1)+'-01':y+'-'+String(mo+1).padStart(2,'0');
}
function budgetFor(n,m){
  let best=null;
  Object.keys(n.budgets).sort().forEach(k=>{if(k<=m&&typeof n.budgets[k]==='number')best=k});
  return best?n.budgets[best]:n.budget;
}
function monthData(n,m){
  const recs=n.records.filter(r=>monthOf(r.date)===m).sort((a,b)=>{
    if(a.date!==b.date)return a.date<b.date?1:-1;
    return (b.ts||0)-(a.ts||0);
  });
  const by={};
  let spent=0;
  recs.forEach(r=>{by[r.cat]=r2((by[r.cat]||0)+r.amount);spent=r2(spent+r.amount)});
  const cats=Object.keys(by).map(k=>({name:k,sum:by[k]})).sort((a,b)=>b.sum-a.sum);
  const budget=budgetFor(n,m);
  return {recs,cats,spent,budget,left:r2(budget-spent)};
}
function monthList(n,cur){
  const set={};
  set[cur]=1;
  n.records.forEach(r=>{const m=monthOf(r.date);if(/^\d{4}-\d{2}$/.test(m))set[m]=1});
  return Object.keys(set).sort();
}

function mount(ctx){
  const {root,el,state,ui,commit,redraw,uid,day}=ctx;
  const size=ctx.size||root.getAttribute('data-size')||'3x3';
  const n=norm(state);
  const cur=day().slice(0,7);
  if(!ui.month)ui.month=cur;
  if(!ui.tab)ui.tab='cat';
  const m=ui.month;
  const md=monthData(n,m);
  const months=monthList(n,cur);
  if(months.indexOf(m)<0){months.push(m);months.sort();}
  const idx=months.indexOf(m);
  const prevM=idx>0?months[idx-1]:null;
  const nextM=idx<months.length-1?months[idx+1]:null;
  const small=size==='3x3';

  function openAdd(){
    ui.draft={rid:uid(),edit:false,amount:'',cat:ui.lastCat||CATS[0],date:m===cur?day():m+'-01',note:''};
    ui.from=ui.view==='detail'?'detail':'main';
    ui.view='form';ui.err='';ui.confirmDel=false;ui.saving=false;
    redraw();
  }
  function openEdit(r){
    ui.draft={rid:r.id,edit:true,amount:String(r.amount),cat:r.cat,date:r.date,note:r.note||''};
    ui.from=ui.view==='detail'?'detail':'main';
    ui.view='form';ui.err='';ui.confirmDel=false;ui.saving=false;
    redraw();
  }
  function openBudget(){
    ui.bdraft=String(md.budget);
    ui.from=ui.view==='detail'?'detail':'main';
    ui.view='budget';ui.err='';ui.saving=false;
    redraw();
  }
  function closeForm(){
    ui.view=ui.from||'main';ui.draft=null;ui.err='';ui.confirmDel=false;ui.saving=false;
    redraw();
  }
  function fail(msg){ui.err=msg;redraw()}
  function failSave(){ui.saving=false;ui.err='保存失败，数据没有改动，请重试';redraw()}

  function save(){
    if(ui.saving)return;
    const d=ui.draft;
    const amt=Number(d.amount);
    if(String(d.amount).trim()===''||!isFinite(amt)||r2(amt)<=0)return fail('请输入大于 0 的金额');
    if(amt>1e9)return fail('金额过大，请检查');
    if(!/^\d{4}-\d{2}-\d{2}$/.test(d.date||''))return fail('请选择日期');
    if(CATS.indexOf(d.cat)<0)return fail('请选择类别');
    const rec={id:d.rid,amount:r2(amt),cat:d.cat,date:d.date,note:String(d.note||'').trim()};
    ui.saving=true;ui.err='';
    commit(s=>{
      const nn=norm(s);
      const old=nn.records.find(r=>r.id===rec.id);
      const full={...rec,ts:(old&&old.ts)?old.ts:Date.now()};
      return {...s,...nn,records:nn.records.filter(r=>r.id!==rec.id).concat([full])};
    },{...ui,view:ui.from||'main',draft:null,err:'',saving:false,confirmDel:false,month:rec.date.slice(0,7),lastCat:rec.cat})
      .then(ok=>{if(ok===false)failSave()}).catch(failSave);
  }
  function removeRec(){
    if(ui.saving)return;
    const id=ui.draft.rid;
    ui.saving=true;
    commit(s=>{
      const nn=norm(s);
      return {...s,...nn,records:nn.records.filter(r=>r.id!==id)};
    },{...ui,view:ui.from||'main',draft:null,err:'',saving:false,confirmDel:false})
      .then(ok=>{if(ok===false)failSave()}).catch(failSave);
  }
  function saveBudget(){
    if(ui.saving)return;
    const v=Number(ui.bdraft);
    if(String(ui.bdraft).trim()===''||!isFinite(v)||r2(v)<=0)return fail('请输入大于 0 的预算金额');
    if(v>1e9)return fail('预算过大，请检查');
    ui.saving=true;ui.err='';
    commit(s=>{
      const nn=norm(s);
      const budgets={...nn.budgets};
      if(m<cur){
        const nx=nextMonth(m);
        if(budgets[nx]===undefined)budgets[nx]=budgetFor(nn,nx);
      }
      budgets[m]=r2(v);
      return {...s,...nn,budgets};
    },{...ui,view:ui.from||'main',err:'',saving:false})
      .then(ok=>{if(ok===false)failSave()}).catch(failSave);
  }

  function head(title,right){
    const kids=[el('button',{type:'button',class:'ib','aria-label':'返回',onclick:closeForm},'‹'),el('div',{class:'ttl'},title)];
    if(right)kids.push(right);
    return el('div',{class:'head'},...kids);
  }
  function errLine(){
    return ui.err?el('div',{class:'err',role:'alert'},'⚠ '+ui.err):el('div',{class:'errgap'});
  }

  function formView(){
    const d=ui.draft;
    const enter=e=>{if(e.key==='Enter')save()};
    const amt=el('input',{type:'number',step:'any',min:'0',placeholder:'0.00','aria-label':'金额',value:d.amount,oninput:e=>{d.amount=e.target.value},onkeydown:enter});
    const sel=el('select',{'aria-label':'类别',onchange:e=>{d.cat=e.target.value}},...CATS.map(c=>el('option',{value:c},c)));
    sel.value=d.cat;
    const dt=el('input',{type:'date','aria-label':'日期',value:d.date,oninput:e=>{d.date=e.target.value},onchange:e=>{d.date=e.target.value}});
    const note=el('input',{type:'text',maxlength:'30',placeholder:'备注（可选）','aria-label':'备注',value:d.note,oninput:e=>{d.note=e.target.value},onkeydown:enter});
    const row=(l,c)=>el('label',{class:'frow'},el('span',{},l),c);
    const body=el('div',{class:'fbody'},row('金额',amt),row('类别',sel),row('日期',dt),row('备注',note));
    let foot;
    if(d.edit&&ui.confirmDel){
      foot=el('div',{class:'ffoot'},
        el('button',{type:'button',class:'btn',onclick:()=>{ui.confirmDel=false;redraw()}},'不删了'),
        el('button',{type:'button',class:'btn sure',disabled:!!ui.saving,onclick:removeRec},'确认删除'));
    }else{
      const kids=[el('button',{type:'button',class:'btn',onclick:closeForm},'取消')];
      if(d.edit)kids.push(el('button',{type:'button',class:'btn danger',onclick:()=>{ui.confirmDel=true;redraw()}},'删除'));
      kids.push(el('button',{type:'button',class:'btn primary',disabled:!!ui.saving,onclick:save},ui.saving?'保存中…':'保存'));
      foot=el('div',{class:'ffoot'},...kids);
    }
    const kids=[];
    if(!small)kids.push(head(d.edit?'修改这笔记录':'记一笔'));
    kids.push(body);
    if(d.edit&&ui.confirmDel)kids.push(el('div',{class:'err',role:'alert'},'⚠ 确定删除这笔 ¥'+fmt(Number(d.amount)||0)+'？删除后无法恢复'));
    else kids.push(errLine());
    kids.push(foot);
    return el('div',{class:'form'},...kids);
  }

  function budgetView(){
    const inp=el('input',{type:'number',step:'any',min:'0',placeholder:'0.00','aria-label':'月预算',value:ui.bdraft,oninput:e=>{ui.bdraft=e.target.value},onkeydown:e=>{if(e.key==='Enter')saveBudget()}});
    const hint=m<cur?'只修改该月的预算，其他月份不变':'从该月起生效，之前月份的预算不变';
    const body=el('div',{class:'fbody'},
      el('label',{class:'frow wide'},el('span',{},monthLabel(m)+'预算（元）'),inp),
      el('div',{class:'hint'},hint));
    const kids=[];
    if(!small)kids.push(head('修改月预算'));
    kids.push(body,errLine(),el('div',{class:'ffoot'},
      el('button',{type:'button',class:'btn',onclick:closeForm},'取消'),
      el('button',{type:'button',class:'btn primary',disabled:!!ui.saving,onclick:saveBudget},ui.saving?'保存中…':'保存')));
    return el('div',{class:'form'},...kids);
  }


  function go(mo){ui.month=mo;redraw()}
  function nav(){
    return el('div',{class:'nav'},
      el('button',{type:'button',class:'ib','aria-label':'上一个有记录的月份',disabled:!prevM,onclick:()=>go(prevM)},'‹'),
      el('div',{class:'lbl'},monthLabel(m)),
      el('button',{type:'button',class:'ib','aria-label':'下一个有记录的月份',disabled:!nextM,onclick:()=>go(nextM)},'›'));
  }
  function barEl(pct,over){
    const i=el('i');
    i.style.width=pct+'%';
    return el('div',{class:'bar'+(over?' over':''),role:'progressbar','aria-valuemin':'0','aria-valuemax':'100','aria-valuenow':String(Math.round(pct))},i);
  }
  function summary(){
    const over=md.left<0;
    const pct=md.budget>0?Math.min(100,md.spent/md.budget*100):0;
    return el('div',{class:'sum'},
      nav(),
      el('div',{class:'lead'},
        el('div',{class:'lab'},over?'⚠ 已超支':(m===cur?'本月还剩':'该月剩余')),
        el('div',{class:'big'+(over?' over':'')},'¥'+fmt(Math.abs(md.left)))),
      barEl(pct,over),
      el('div',{class:'meta'},
        el('span',{},'已花 ¥'+fmt(md.spent)),
        el('button',{type:'button',class:'bud','aria-label':'修改本月预算',onclick:openBudget},'预算 ¥'+fmt(md.budget)+' ✎')));
  }
  function catList(){
    if(!md.cats.length)return el('div',{class:'empty'},'这个月还没有支出');
    const top=md.cats[0].sum;
    return el('div',{class:'clist'},...md.cats.map(c=>{
      const i=el('i');
      i.style.width=(top>0?Math.max(4,c.sum/top*100):0)+'%';
      return el('div',{class:'crow',title:c.name+' '+Math.round(c.sum/md.spent*100)+'%'},
        el('span',{class:'cn'},c.name),
        el('span',{class:'cb'},i),
        el('span',{class:'ca'},'¥'+fmt(c.sum)));
    }));
  }
  function recList(){
    if(!md.recs.length)return el('div',{class:'empty'},'这个月还没有记账');
    return el('div',{class:'rlist'},...md.recs.map(r=>el('button',{type:'button',class:'rrow','aria-label':'修改 '+r.date+' '+r.cat+' '+fmt(r.amount)+'元',onclick:()=>openEdit(r)},
      el('span',{class:'rd'},r.date.slice(5)),
      el('span',{class:'rm'},el('b',{},r.cat),...(r.note?[el('em',{},r.note)]:[])),
      el('span',{class:'ra'},'¥'+fmt(r.amount)))));
  }
  function tabs(){
    const t=(k,label)=>el('button',{type:'button',role:'tab',class:ui.tab===k?'on':'','aria-selected':ui.tab===k?'true':'false',onclick:()=>{ui.tab=k;redraw()}},label);
    return el('div',{class:'tabs',role:'tablist'},t('cat','各类花费'),t('rec','流水 '+md.recs.length));
  }
  function listArea(){return el('div',{class:'scroll'},ui.tab==='cat'?catList():recList())}
  function addBtn(){return el('button',{type:'button',class:'btn primary',onclick:openAdd},'＋ 记一笔')}

  function detailView(){
    return el('div',{class:'detail'},
      el('div',{class:'head'},
        el('button',{type:'button',class:'ib','aria-label':'返回',onclick:()=>{ui.view='main';redraw()}},'‹'),
        el('div',{class:'ttl'},monthLabel(m)+' · 还剩 ¥'+fmt(md.left)),
        el('button',{type:'button',class:'ib add','aria-label':'记一笔',onclick:openAdd},'＋')),
      tabs(),listArea());
  }
  function mainNodes(){
    if(size==='6x3'){
      return [el('div',{class:'cols'},
        el('div',{class:'pane p1 spread'},summary(),addBtn()),
        el('div',{class:'pane p2'},tabs(),listArea()))];
    }
    if(size==='3x6'){
      return [summary(),tabs(),listArea(),addBtn()];
    }
    if(size==='6x6'){
      return [summary(),el('div',{class:'cols'},
        el('div',{class:'pane p1'},el('div',{class:'st'},'各类花费'),el('div',{class:'scroll'},catList())),
        el('div',{class:'pane p2'},el('div',{class:'st'},'流水 · '+md.recs.length+' 笔'),el('div',{class:'scroll'},recList()))),
        addBtn()];
    }
    return [summary(),el('div',{class:'btns'},addBtn(),
      el('button',{type:'button',class:'btn',onclick:()=>{ui.view='detail';redraw()}},'明细'))];
  }

  let nodes;
  if(ui.view==='form'&&ui.draft)nodes=[formView()];
  else if(ui.view==='budget')nodes=[budgetView()];
  else if(ui.view==='detail')nodes=[detailView()];
  else nodes=mainNodes();
  nodes.forEach(x=>root.appendChild(x));
